rows=[]
for p in sorted((V/'finalists').glob('*.allorders.json')):
    tag=p.name.removesuffix('.allorders.json');s=V/'finalists'/tag
    if not s.with_suffix('.qasm').exists() or not s.with_suffix('.verified30.json').exists():continue
    a=read(p);md=read(s.with_suffix('.json'));pr=read(s.with_suffix('.screen.json')) if s.with_suffix('.screen.json').exists() else {}
    ver=read(s.with_suffix('.verified30.json')) if s.with_suffix('.verified30.json').exists() else None
    gate=read(s.with_suffix('.gate.json')) if s.with_suffix('.gate.json').exists() else None
    mc=None;seeds=[]
    if s.with_suffix('.mc.log').exists():
        text=s.with_suffix('.mc.log').read_text();match=re.search(r' mean ([0-9.e+-]+)',text)
        if match:mc=float(match[1])
        seeds=[dict(seed=int(x),loss=float(y),acceptance=float(z)) for x,y,z in re.findall(r' (0|1000|2000) ([0-9.e+-]+) .*? acc ([0-9.]+)',text)]
    rows.append(dict(tag=tag,allorders=a,price=pr,metadata=md,reference=bool(ver and ver['reference']['returncode']==0),gate=gate,mc=mc,seeds=seeds))
if (V/'evidence_index.json').exists():
    evidence=read(V/'evidence_index.json');rows=evidence['rows'];receipts=evidence['receipts']
else:
    receipts={p.name:read(p) for p in sorted((V/'runs').glob('*.receipt.json'))}
    (V/'evidence_index.json').write_text(json.dumps(dict(rows=rows,receipts=receipts),indent=2))
